const DB_FILE = __DIR__ . '/data/store.json';

function db_read(): array { return json_decode(file_get_contents(DB_FILE), true, 512, JSON_THROW_ON_ERROR); }
function db_update(callable $callback): mixed {
    $fp = fopen(DB_FILE, 'c+'); if (!$fp || !flock($fp, LOCK_EX)) throw new RuntimeException('Could not open the local data store.');
    rewind($fp); $raw = stream_get_contents($fp); $db = json_decode($raw ?: '{}', true, 512, JSON_THROW_ON_ERROR);
    try { $result = $callback($db); rewind($fp); ftruncate($fp, 0); fwrite($fp, json_encode($db, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR)); fflush($fp); return $result; }
    finally { flock($fp, LOCK_UN); fclose($fp); }
}
function respond(mixed $data, int $status=200): never { http_response_code($status); header('Content-Type: application/json; charset=utf-8'); echo json_encode(['success'=>$status<400,'data'=>$status<400?$data:null,'message'=>$status>=400?$data:null], JSON_UNESCAPED_SLASHES); exit; }
function input(): array { return json_decode(file_get_contents('php://input') ?: '{}', true) ?: []; }
function require_user(array $db): array { $id=$_SESSION['uid']??''; foreach($db['users'] as $u) if($u['id']===$id&&($u['active']??true)) return $u; respond('Please sign in to continue.',401); }
function require_admin(array $db): array { $u=require_user($db); if($u['role']!=='admin') respond('Administrator access required.',403); return $u; }
function book_by_id(array $db,string $id): ?array { foreach($db['books'] as $b) if($b['id']===$id)return $b; return null; }
function user_public(?array $u): ?array { return $u ? ['id'=>$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']] : null; }
